export type TopicStatus = "queued" | "in-progress" | "revisit" | "applied";

export type FeedbackKind =
  | "clear"
  | "too-broad"
  | "too-abstract"
  | "already-familiar"
  | "needs-example"
  | "needs-exercise";

export type LessonTheory = {
  readonly problem: string;
  readonly model: string;
  readonly mechanics: string;
  readonly pitfalls: readonly string[];
  readonly whenNot: string;
};

export type LessonExample = {
  readonly title: string;
  readonly code: string;
  readonly explanation: string;
};

// Structured section content. A section either keeps the legacy flat
// `paragraphs` list or provides `blocks`; the reader renders blocks when
// present. Inline markup inside any text: **bold**, *italic*, `code`.
export type SectionBlock =
  | { readonly kind: "p"; readonly text: string }
  | {
      readonly kind: "list";
      readonly ordered?: boolean;
      readonly items: readonly string[];
    }
  | {
      readonly kind: "callout";
      readonly variant: "key" | "warning";
      readonly title?: string;
      readonly text: string;
    };

export type LessonSection = {
  readonly heading: string | null;
  readonly paragraphs?: readonly string[];
  readonly blocks?: readonly SectionBlock[];
  readonly examples?: readonly LessonExample[];
};

export type DeepLesson = {
  readonly sections: readonly LessonSection[];
};

export type TopicCard = {
  readonly id: string;
  readonly title: string;
  readonly summary: string;
  readonly concepts: readonly string[];
  readonly practicePrompt: string;
  readonly checkPrompt: string;
  readonly tier?: number;
  readonly complexity?: number;
  readonly proofBrief?: string;
  readonly references?: readonly string[];
  readonly objectives?: readonly string[];
  readonly lesson?: LessonTheory;
  readonly deepLesson?: DeepLesson;
  readonly examples?: readonly LessonExample[];
};

export type PracticeArea = {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly topics: readonly TopicCard[];
  readonly tier?: number;
  readonly dependencies?: readonly string[];
};

